window.filterFinanceNavigationByPermissions = function() {
  const nav = $('nav');
  if (!nav) return;
  const buttons = nav.querySelectorAll('button[data-page]');
  let firstVisiblePage = null;
  buttons.forEach(b => {
    const p = b.dataset.page;
    const perm = FINANCE_PAGE_PERM_MAP[p];
    const allowed = (typeof window.hasPermission === 'function' && perm) ? window.hasPermission(perm) : true;
    b.style.display = allowed ? '' : 'none';
    if (allowed && !firstVisiblePage) firstVisiblePage = p;
  });
  const currentPerm = FINANCE_PAGE_PERM_MAP[page];
  if (typeof window.hasPermission === 'function' && currentPerm && !window.hasPermission(currentPerm)) {
    if (firstVisiblePage) {
      page = firstVisiblePage;
      render();
    }
  }
};

