function setKind(){const m=maps[$('kind').value];['debit','credit'].forEach((id,i)=>$(id).innerHTML=m[i].map(a=>`<option value="${a}">${name(a)}</option>`).join(''))}function openEntry(k='income'){$('form').reset();$('kind').value=k;$('date').value=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'});if(!$('date').value)$('date').value=new Date().toISOString().slice(0,10);$('formerror').textContent='';setKind();$('entry').showModal()}$('kind').onchange=setKind;
$('form').onsubmit=e=>{e.preventDefault();const a=Number($('amount').value);if(!Number.isSafeInteger(a)||a<=0||a>999999999999||$('debit').value===$('credit').value||!$('memo').value.trim()){ $('formerror').textContent='Isi uraian dan nominal rupiah bulat positif. Akun debit dan kredit harus berbeda.';return}const item={id:uid(),date:$('date').value,amount:a,memo:$('memo').value.trim(),party:$('party').value.trim(),debit:$('debit').value,credit:$('credit').value};if(persist({...state,entries:[...state.entries,item]})){$('entry').close();render();toast('Transaksi tersimpan. Laporan diperbarui.');if(window.GoogleSheetsSync){window.GoogleSheetsSync.pushRecord('addFinanceEntry',item);}}};
