function resolveAccount(val){
  if(!val)return null;
  const s=String(val).trim().toLowerCase();
  let found=accounts.find(a=>a[0]===s);
  if(found)return found[0];
  found=accounts.find(a=>s.startsWith(a[0]));
  if(found)return found[0];
  found=accounts.find(a=>a[1].toLowerCase()===s);
  if(found)return found[0];
  found=accounts.find(a=>a[1].toLowerCase().includes(s)||s.includes(a[1].toLowerCase()));
  if(found)return found[0];
  return null;
}

function parseExcelDate(val){
  if (val === null || val === undefined || val === "") {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
  }

  // 1. If Date object: extract UTC components to avoid timezone drift
  if (val instanceof Date && !isNaN(val.getTime())) {
    const y = val.getUTCFullYear();
    const m = String(val.getUTCMonth() + 1).padStart(2, "0");
    const d = String(val.getUTCDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  }

  // 2. If Excel serial number (e.g. 46326 for 2026-10-31)
  if (typeof val === "number") {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const d = new Date(excelEpoch.getTime() + Math.round(val * 86400 * 1000));
    if (!isNaN(d.getTime())) {
      const y = d.getUTCFullYear();
      const m = String(d.getUTCMonth() + 1).padStart(2, "0");
      const day = String(d.getUTCDate()).padStart(2, "0");
      return `${y}-${m}-${day}`;
    }
  }

  const s = String(val).trim();
  if (!s) return "2026-10-31";

  // 3. If standard ISO YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;

  // 4. If DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
  const m1 = s.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})$/);
  if (m1) {
    let part1 = parseInt(m1[1], 10);
    let part2 = parseInt(m1[2], 10);
    let year = m1[3];
    let day = part1;
    let month = part2;
    if (part1 <= 12 && part2 > 12) {
      day = part2;
      month = part1;
    }
    return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
  }

  // 5. If DD/MM/YY or DD-MM-YY
  const m2 = s.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2})$/);
  if (m2) {
    let day = parseInt(m2[1], 10);
    let month = parseInt(m2[2], 10);
    let year = 2000 + parseInt(m2[3], 10);
    if (day <= 12 && month > 12) {
      const tmp = day; day = month; month = tmp;
    }
    return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
  }

  // 6. Textual months: e.g. "31 Oct 2026", "31-Oct-26", "31 Oktober 2026", "Oct 31, 2026"
  const monthMap = {
    jan: 1, januari: 1, january: 1,
    feb: 2, februari: 2, february: 2,
    mar: 3, maret: 3, march: 3,
    apr: 4, april: 4,
    mei: 5, may: 5,
    jun: 6, juni: 6, june: 6,
    jul: 7, juli: 7, july: 7,
    agu: 8, ags: 8, agus: 8, agt: 8, agustus: 8, aug: 8, august: 8,
    sep: 9, september: 9,
    okt: 10, oktober: 10, oct: 10, october: 10,
    nov: 11, nopember: 11, november: 11,
    des: 12, desember: 12, dec: 12, december: 12
  };

  const textPattern = /^(\d{1,2})[\s\-]+([a-zA-Z]+)[\s\-]+(\d{2,4})$/;
  const mt = s.match(textPattern);
  if (mt) {
    const day = String(mt[1]).padStart(2, "0");
    const monName = mt[2].toLowerCase();
    let yr = parseInt(mt[3], 10);
    if (yr < 100) yr += 2000;
    const moNum = monthMap[monName];
    if (moNum) {
      return `${yr}-${String(moNum).padStart(2, "0")}-${day}`;
    }
  }

  const textPatternRev = /^([a-zA-Z]+)[\s\-]+(\d{1,2})[,\s\-]+(\d{2,4})$/;
  const mr = s.match(textPatternRev);
  if (mr) {
    const monName = mr[1].toLowerCase();
    const day = String(mr[2]).padStart(2, "0");
    let yr = parseInt(mr[3], 10);
    if (yr < 100) yr += 2000;
    const moNum = monthMap[monName];
    if (moNum) {
      return `${yr}-${String(moNum).padStart(2, "0")}-${day}`;
    }
  }

  // 7. Pure numeric serial in string (e.g. "46326")
  if (/^\d{5}$/.test(s)) {
    const serial = parseInt(s, 10);
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const d = new Date(excelEpoch.getTime() + Math.round(serial * 86400 * 1000));
    if (!isNaN(d.getTime())) {
      const y = d.getUTCFullYear();
      const m = String(d.getUTCMonth() + 1).padStart(2, "0");
      const day = String(d.getUTCDate()).padStart(2, "0");
      return `${y}-${m}-${day}`;
    }
  }

  // 8. Safe fallback using local date components (never toISOString())
  const parsed = new Date(s);
  if (!isNaN(parsed.getTime())) {
    const y = parsed.getFullYear();
    const m = String(parsed.getMonth() + 1).padStart(2, "0");
    const d = String(parsed.getDate()).padStart(2, "0");
    return `${y}-${m}-${day}`;
  }

  return "2026-10-31";
}

function parseAmount(val){
  if(typeof val==='number')return Math.round(val);
  if(!val)return 0;
  let s=String(val).replace(/[^\d.,-]/g,'').trim();
  if(s.includes('.')&&s.includes(',')){
    s=s.replace(/\./g,'').replace(',','.');
  }else if(s.includes('.')&&!s.includes(',')){
    const parts=s.split('.');
    if(parts.length>2||(parts.length===2&&parts[1].length===3)){
      s=s.replace(/\./g,'');
    }
  }else if(s.includes(',')){
    s=s.replace(/,/g,'');
  }
  const n=parseInt(s,10);
  return isNaN(n)?0:n;
}

