async function handleExcelImport(event){
  const file=event.target.files[0];
  if(!file)return;
  event.target.value='';

  if(typeof XLSX==='undefined'){
    alert('Pustaka pembaca Excel sedang dimuat. Silakan coba sesaat lagi.');
    return;
  }

  try{
    const buffer=await file.arrayBuffer();
    const workbook=XLSX.read(buffer,{type:'array',cellDates:false});
    const firstSheetName=workbook.SheetNames[0];
    const worksheet=workbook.Sheets[firstSheetName];
    const rows=XLSX.utils.sheet_to_json(worksheet,{header:1,defval:'',blankrows:false});

    if(rows.length<2){
      alert('File Excel kosong atau tidak memiliki data setelah baris judul.');
      return;
    }

    let headerRowIdx=0;
    for(let i=0;i<Math.min(5,rows.length);i++){
      const rowStr=rows[i].map(c=>String(c).toLowerCase()).join(' ');
      if(rowStr.includes('tanggal')||rowStr.includes('uraian')||rowStr.includes('nominal')||rowStr.includes('debit')){
        headerRowIdx=i;
        break;
      }
    }

    const headers=rows[headerRowIdx].map(c=>String(c).toLowerCase().trim());
    let colDate=headers.findIndex(h=>h.includes('tanggal')||h==='date');
    let colMemo=headers.findIndex(h=>h.includes('uraian')||h.includes('transaksi')||h.includes('keterangan')||h.includes('memo'));
    let colParty=headers.findIndex(h=>h.includes('referensi')||h.includes('member')||h.includes('vendor')||h.includes('pihak')||h.includes('party'));
    let colDebit=headers.findIndex(h=>h.includes('debit')||h.includes('kode debit'));
    let colCredit=headers.findIndex(h=>h.includes('kredit')||h.includes('credit'));
    let colAmount=headers.findIndex(h=>h.includes('nominal')||h.includes('jumlah')||h.includes('amount')||h.includes('rupiah'));

    if(colDate===-1)colDate=0;
    if(colMemo===-1)colMemo=1;
    if(colParty===-1)colParty=2;
    if(colDebit===-1)colDebit=3;
    if(colCredit===-1)colCredit=4;
    if(colAmount===-1)colAmount=5;

    const imported=[];
    const errors=[];

    for(let i=headerRowIdx+1;i<rows.length;i++){
      const row=rows[i];
      if(!row||row.every(cell=>String(cell).trim()===''))continue;

      const rawDate=row[colDate];
      const rawMemo=String(row[colMemo]||'').trim();
      const rawParty=String(colParty!==-1?row[colParty]||'':'').trim();
      const rawDebit=row[colDebit];
      const rawCredit=row[colCredit];
      const rawAmount=row[colAmount];

      if(!rawMemo&&!rawAmount)continue;

      const date=parseExcelDate(rawDate);
      const amount=parseAmount(rawAmount);
      const debit=resolveAccount(rawDebit);
      const credit=resolveAccount(rawCredit);

      if(!amount||amount<=0){
        errors.push(`Baris ${i+1}: Nominal tidak valid (${rawAmount})`);
        continue;
      }
      if(!debit){
        errors.push(`Baris ${i+1}: Akun debit tidak dikenali (${rawDebit||'kosong'})`);
        continue;
      }
      if(!credit){
        errors.push(`Baris ${i+1}: Akun kredit tidak dikenali (${rawCredit||'kosong'})`);
        continue;
      }
      if(debit===credit){
        errors.push(`Baris ${i+1}: Akun debit dan kredit tidak boleh sama (${name(debit)})`);
        continue;
      }

      imported.push({
        id: uid(),
        date: date,
        memo: rawMemo||'Transaksi impor Excel',
        party: rawParty,
        debit: debit,
        credit: credit,
        amount: amount
      });
    }

    if(imported.length===0){
      alert('Tidak ada transaksi valid yang dapat diimpor.\n\nPeriksa kendala berikut:\n'+errors.slice(0,5).join('\n'));
      return;
    }

    let confirmMsg=`Ditemukan ${imported.length} transaksi valid dari file "${file.name}".\n\nTambahkan ke pembukuan sekarang?`;
    if(errors.length>0){
      confirmMsg+=`\n\n(Catatan: ${errors.length} baris dilewati karena format tidak sesuai).`;
    }

    if(confirm(confirmMsg)){
      const nextEntries=[...state.entries,...imported];
      if(persist({...state,entries:nextEntries})){
        render();
        toast(`Berhasil mengimpor ${imported.length} transaksi dari Excel!`);
      }
    }
  }catch(err){
    console.error(err);
    alert('Gagal membaca file Excel. Pastikan file tidak terproteksi kata sandi.');
  }
}



