async function handlePettyCashExcelImport(event) {
  const file = event.target.files[0];
  if (!file) return;

  try {
    const data = await file.arrayBuffer();
    const workbook = XLSX.read(data, { type: 'array', cellDates: false });
    
    if (!workbook.SheetNames || workbook.SheetNames.length === 0) {
      alert('File Excel kosong atau tidak memiliki sheet.');
      return;
    }

    const newRecords = [];
    let grandMasuk = 0;
    let grandKeluar = 0;
    let sheetCount = 0;

    for (const sheetName of workbook.SheetNames) {
      const ws = workbook.Sheets[sheetName];
      if (!ws) continue;
      const rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false });
      if (!rows || rows.length === 0) continue;

      let headerIdx = -1;
      let colNo = 0, colDate = 1, colMemo = 2, colIn = 3, colOut = 4, colBal = 5;

      for (let r = 0; r < Math.min(10, rows.length); r++) {
        const row = rows[r] || [];
        const strRow = row.map(c => String(c || '').toLowerCase().trim());
        const hasDate = strRow.some(c => c.includes('tanggal') || c.includes('tgl') || c.includes('date'));
        const hasMemo = strRow.some(c => c.includes('keterangan') || c.includes('uraian') || c.includes('deskripsi') || c.includes('pengeluaran') || c.includes('item'));
        if (hasDate || hasMemo) {
          headerIdx = r;
          const fNo = strRow.findIndex(c => c === 'no' || c === 'no.' || c.includes('nomor'));
          if (fNo !== -1) colNo = fNo;
          const fDate = strRow.findIndex(c => c.includes('tanggal') || c.includes('tgl') || c.includes('date'));
          if (fDate !== -1) colDate = fDate;
          const fMemo = strRow.findIndex(c => c.includes('keterangan') || c.includes('uraian') || c.includes('deskripsi') || c.includes('item'));
          if (fMemo !== -1) colMemo = fMemo;
          const fIn = strRow.findIndex(c => c.includes('masuk') || c.includes('in') || c.includes('refill') || c.includes('debit'));
          if (fIn !== -1) colIn = fIn;
          const fOut = strRow.findIndex(c => c.includes('keluar') || c.includes('out') || c.includes('kredit') || c.includes('biaya'));
          if (fOut !== -1) colOut = fOut;
          const fBal = strRow.findIndex(c => c.includes('saldo') || c.includes('balance') || c.includes('sisa'));
          if (fBal !== -1) colBal = fBal;
          break;
        }
      }

      if (headerIdx === -1) {
        for (let r = 0; r < rows.length; r++) {
          const row = rows[r] || [];
          if (row.length >= 3 && String(row[colMemo] || '').trim().toLowerCase().includes('petty')) {
            headerIdx = r - 1;
            break;
          }
        }
      }

      if (headerIdx === -1) continue;
      sheetCount++;

      let lastDate = '';
      let runningSaldo = 0;

      for (let r = headerIdx + 1; r < rows.length; r++) {
        const row = rows[r] || [];
        if (!row || row.every(c => String(c || '').trim() === '')) continue;

        const rawMemo = String(row[colMemo] || '').trim();
        const rawNo = row[colNo];
        const rawDate = row[colDate];
        const rawIn = row[colIn];
        const rawOut = row[colOut];
        const rawBal = colBal !== -1 ? row[colBal] : null;

        if (!rawMemo && !rawIn && !rawOut) continue;
        if (rawMemo.toLowerCase().startsWith('total') || rawMemo.toLowerCase().startsWith('jumlah')) continue;

        let dateStr = '';
        if (rawDate) {
          dateStr = parseExcelDate(rawDate);
          lastDate = dateStr;
        }

        const masuk = parseAmount(rawIn) || 0;
        const keluar = parseAmount(rawOut) || 0;
        
        let saldo = null;
        if (rawBal !== null && rawBal !== undefined && String(rawBal).trim() !== '') {
          saldo = parseAmount(rawBal);
          runningSaldo = saldo;
        } else {
          runningSaldo += (masuk - keluar);
          saldo = runningSaldo;
        }

        grandMasuk += masuk;
        grandKeluar += keluar;

        newRecords.push({
          id: 'pc-' + uid(),
          sheet: sheetName,
          no: rawNo ? Number(rawNo) : newRecords.length + 1,
          date: dateStr,
          effectiveDate: dateStr || lastDate,
          keterangan: rawMemo,
          masuk: masuk,
          keluar: keluar,
          saldo: saldo
        });
      }
    }

    if (newRecords.length === 0) {
      alert('Tidak ditemukan baris transaksi petty cash yang cocok pada file Excel. Pastikan terdapat kolom TANGGAL, KETERANGAN, UANG MASUK, UANG KELUAR, dan SALDO.');
      return;
    }

    const confirmMsg = `Berhasil membaca file Excel "${file.name}":\n` +
      `• Terdeteksi ${sheetCount} Sheet\n` +
      `• Total ${newRecords.length} Catatan Petty Cash\n` +
      `• Total Uang Masuk: ${money(grandMasuk)}\n` +
      `• Total Pengeluaran: ${money(grandKeluar)}\n` +
      `• Sisa Saldo: ${money(newRecords[newRecords.length - 1]?.saldo || (grandMasuk - grandKeluar))}\n\n` +
      `Perbarui data Petty Cash Admin dengan file ini?`;

    if (confirm(confirmMsg)) {
      pettyCashData = newRecords;
      localStorage.setItem(PETTY_CASH_KEY, JSON.stringify(pettyCashData));
      pettyCashFilterSheet = 'ALL';
      pettyCashSearch = '';
      render();
      toast(`Petty Cash Admin berhasil diperbarui (${newRecords.length} catatan)!`);
    }
  } catch (err) {
    console.error(err);
    alert('Terjadi kesalahan saat membaca file Excel: ' + (err.message || err));
  } finally {
    event.target.value = '';
  }
}


