window.renderFinance = function(targetPage) {
  if (targetPage && pages[targetPage]) {
    page = targetPage;
  }
  render();
};

window.getFinanceCashBalance = function() {
  return balance('1001') + balance('1002') + balance('1003');
};

window.getFinanceQuickStats = function() {
  const all = (state && state.entries) ? state.entries : [];
  const cash = balance('1001') + balance('1002') + balance('1003');
  const income = -sum('income', all);
  const expense = sum('expense', all);
  const netProfit = income - expense;
  return {
    cashBalance: cash,
    totalIncome: income,
    totalExpense: expense,
    netProfit: netProfit,
    totalEntries: all.length
  };
};

window.addStudioIncomeToFinance = function(booking) {
  try {
    const today = new Date().toLocaleDateString('en-CA', {timeZone: 'Asia/Jakarta'}) || new Date().toISOString().slice(0, 10);
    const amount = Number(booking.finalPrice || booking.amount || 0);
    if (!amount || amount <= 0) {
      alert('Nominal transaksi reservasi tidak valid atau nol.');
      return false;
    }
    const memo = `Pendapatan Booking: ${booking.className || 'Kelas Pilates'} [${booking.bookingCode || 'PLT'}] (${booking.paymentOption === 'buy_pack' ? 'Beli Paket' : 'Single Session'})`;
    const party = booking.clientName || 'Member Studio';
    
    // Check if duplicate entry already exists for this booking code
    const alreadyExists = (state && state.entries) ? state.entries.some(e => e.memo && e.memo.includes(booking.bookingCode)) : false;
    if (alreadyExists) {
      if (!confirm(`Transaksi untuk kode booking ${booking.bookingCode} sudah pernah dicatat di INCA Finance. Apakah Anda tetap ingin mencatat ulang?`)) {
        return false;
      }
    }

    const entry = {
      id: uid(),
      date: booking.date || today,
      amount: amount,
      memo: memo,
      party: party,
      debit: '1002', // Bank (1002)
      credit: '4001' // Pendapatan kelas Pilates (4001)
    };
    
    const next = { ...state, entries: [entry, ...(state.entries || [])] };
    if (persist(next)) {
      render();
      toast(`Pendapatan ${party} (${money(amount)}) berhasil dicatat ke INCA Finance!`);
      if (typeof window.updateMasterTopBannerStats === 'function') {
        window.updateMasterTopBannerStats();
      }
      return true;
    }
  } catch(err) {
    console.error('Error adding studio income:', err);
    alert('Gagal mencatat transaksi ke INCA Finance: ' + err.message);
  }
  return false;
};
